        guard log.topics.count == 2 else { throw WrapperError.eventMismatch }
        guard log.topics.first == event.topic else { throw WrapperError.eventMismatch }
        guard let decoded = ABIDecoder.decode(types: event.inputs.filter { !$0.indexed }.map { $0.type }, data: log.data) else { throw WrapperError.invalidValue("BurnChunk(address,uint256,uint256,uint64)") }
        let topic0 = log.topics[1]
        guard topic0.count == 32 else { throw WrapperError.invalidValue("event topic 0") }
        guard let raw0 = ABIDecoder.decode(types: [event.inputs[0].type], data: topic0)?.first else { throw WrapperError.invalidValue("event field 0") }
        let value0 = try _cast(raw0, as: EthereumAddress.self)
        let value1 = try _cast(decoded[0], as: BigUInt.self)
        let value2 = try _cast(decoded[1], as: BigUInt.self)
        let value3 = try _cast(decoded[2], as: BigUInt.self)
        return BurnChunkEvent(token: value0, amount: value1, limitPrice: value2, block_: value3)
    }

    private static func _eventDsBurned() throws -> ABI.Element.Event {
        guard let event = try _contract().abi.compactMap({ element -> ABI.Element.Event? in
            if case .event(let value) = element { return value }
            return nil
        }).first(where: { $0.signature == "DsBurned(uint256,uint256)" }) else { throw WrapperError.invalidValue("DsBurned(uint256,uint256)") }
        return event
    }

    /// Builds indexed topics for `DsBurned(uint256,uint256)`. Reference values use their 32-byte topic hashes.
    public static func filterDsBurned() throws -> [EventFilterParameters.Topic?] {
        let event = try _eventDsBurned()
        let topics: [EventFilterParameters.Topic?] = [.string("0x" + event.topic.map { String(format: "%02x", $0) }.joined())]
        return topics
    }

    /// Decodes a `DsBurned(uint256,uint256)` log.
    public static func decodeDsBurnedEvent(_ log: EventLog) throws -> DsBurnedEvent {
        let event = try _eventDsBurned()
        guard log.topics.count == 1 else { throw WrapperError.eventMismatch }
        guard log.topics.first == event.topic else { throw WrapperError.eventMismatch }
        guard let decoded = ABIDecoder.decode(types: event.inputs.filter { !$0.indexed }.map { $0.type }, data: log.data) else { throw WrapperError.invalidValue("DsBurned(uint256,uint256)") }
        let value0 = try _cast(decoded[0], as: BigUInt.self)
        let value1 = try _cast(decoded[1], as: BigUInt.self)
        return DsBurnedEvent(amount: value0, cumulativeBurnedDs: value1)
    }

    /// A decoded custom ABI error.
    public enum DecodedCustomError {
        /// `BuybackBurnCallFailed()`.
        case buybackBurnCallFailed(BuybackBurnCallFailedError)
        /// `UnapprovedAsset()`.
        case unapprovedAsset(UnapprovedAssetError)
        /// `WindowAlreadyOpen()`.
        case windowAlreadyOpen(WindowAlreadyOpenError)
        /// `ZeroAmount()`.
        case zeroAmount(ZeroAmountError)
    }

    /// Decodes a custom revert payload, or returns nil for an unknown selector.
    public static func decodeCustomError(_ data: Data) throws -> DecodedCustomError? {
        guard data.count >= 4 else { throw WrapperError.invalidValue("error selector") }
        let contract = try _contract()
        let selector = Data(data.prefix(4))
        if selector == Data([0xda, 0x79, 0x9f, 0xee]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "BuybackBurnCallFailed()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("BuybackBurnCallFailed()") }
            return .buybackBurnCallFailed(BuybackBurnCallFailedError())
        }
        if selector == Data([0x78, 0x34, 0x67, 0xcb]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "UnapprovedAsset()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("UnapprovedAsset()") }
            return .unapprovedAsset(UnapprovedAssetError())
        }
        if selector == Data([0x5b, 0xf8, 0x9e, 0x4b]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "WindowAlreadyOpen()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("WindowAlreadyOpen()") }
            return .windowAlreadyOpen(WindowAlreadyOpenError())
        }
        if selector == Data([0x1f, 0x2a, 0x20, 0x05]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "ZeroAmount()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("ZeroAmount()") }
            return .zeroAmount(ZeroAmountError())
        }
        return nil
    }
